// ============================================================================
// Convenience type: the Database shape expected by Supabase's typed client
// ============================================================================

export interface Database {
  public: {
    Tables: {
      tenants: { Row: TenantRow; Insert: Partial<TenantRow>; Update: Partial<TenantRow> };
      user_profiles: { Row: UserProfileRow; Insert: Partial<UserProfileRow>; Update: Partial<UserProfileRow> };
      account_approval_requests: { Row: AccountApprovalRequestRow; Insert: Partial<AccountApprovalRequestRow>; Update: Partial<AccountApprovalRequestRow> };
      roles: { Row: RoleRow; Insert: Partial<RoleRow>; Update: Partial<RoleRow> };
      permissions: { Row: PermissionRow; Insert: Partial<PermissionRow>; Update: Partial<PermissionRow> };
      academic_years: { Row: AcademicYearRow; Insert: Partial<AcademicYearRow>; Update: Partial<AcademicYearRow> };
      academic_levels: { Row: AcademicLevelRow; Insert: Partial<AcademicLevelRow>; Update: Partial<AcademicLevelRow> };
      classes: { Row: ClassRow; Insert: Partial<ClassRow>; Update: Partial<ClassRow> };
      subjects: { Row: SubjectRow; Insert: Partial<SubjectRow>; Update: Partial<SubjectRow> };
      parents: { Row: ParentRow; Insert: Partial<ParentRow>; Update: Partial<ParentRow> };
      students: { Row: StudentRow; Insert: Partial<StudentRow>; Update: Partial<StudentRow> };
      payments: { Row: PaymentRow; Insert: Partial<PaymentRow>; Update: Partial<PaymentRow> };
      installments: { Row: InstallmentRow; Insert: Partial<InstallmentRow>; Update: Partial<InstallmentRow> };
      ledger_entries: { Row: LedgerEntryRow; Insert: Partial<LedgerEntryRow>; Update: Partial<LedgerEntryRow> };
      expense_tickets: { Row: ExpenseTicketRow; Insert: Partial<ExpenseTicketRow>; Update: Partial<ExpenseTicketRow> };
      personnel: { Row: PersonnelRow; Insert: Partial<PersonnelRow>; Update: Partial<PersonnelRow> };
      audit_logs: { Row: AuditLogRow; Insert: Partial<AuditLogRow>; Update: Partial<AuditLogRow> };
      notifications: { Row: NotificationRow; Insert: Partial<NotificationRow>; Update: Partial<NotificationRow> };
    };
    Views: {
      vw_dashboard_kpis: { Row: Record<string, unknown> };
      vw_student_roster: { Row: Record<string, unknown> };
      vw_personnel_directory: { Row: Record<string, unknown> };
      vw_audit_log_with_actor: { Row: AuditLogRow & { actor_email: string | null; actor_display_name: string | null } };
    };
    Functions: {
      current_tenant_id: { Args: Record<string, never>; Returns: string };
      current_user_profile_id: { Args: Record<string, never>; Returns: string };
      current_user_roles: { Args: Record<string, never>; Returns: string[] };
      current_user_permissions: { Args: Record<string, never>; Returns: string[] };
      has_permission: { Args: { p_code: string }; Returns: boolean };
      has_role: { Args: { r_code: string }; Returns: boolean };
      write_audit_log: {
        Args: {
          p_tenant_id: string;
          p_action: string;
          p_entity_type: string;
          p_entity_id?: string | null;
          p_actor_id?: string | null;
          p_actor_name?: string | null;
          p_actor_role?: string | null;
          p_session_id?: string | null;
          p_before_json?: unknown;
          p_after_json?: unknown;
          p_note?: string | null;
          p_ip_address?: string | null;
          p_user_agent?: string | null;
          p_request_id?: string | null;
        };
        Returns: string;
      };
      compute_account_balance: { Args: { p_account_id: string }; Returns: number };
      compute_parent_outstanding: { Args: { p_parent_id: string }; Returns: number };
      compute_overdue_amount: { Args: { p_parent_id: string; p_as_of?: string }; Returns: number };
      generate_activation_code: { Args: { p_tenant_id: string }; Returns: string };
      bind_activation_code: { Args: { p_tenant_id: string; p_code: string; p_auth_user_id: string }; Returns: unknown };
      approve_account_request: {
        Args: {
          p_request_id: string;
          p_reviewer_profile_id: string;
          p_target_parent_id?: string | null;
          p_target_student_id?: string | null;
          p_decision_note?: string | null;
        };
        Returns: string;
      };
      reject_account_request: {
        Args: { p_request_id: string; p_reviewer_profile_id: string; p_decision_note: string };
        Returns: void;
      };
      batch_register_family: {
        Args: {
          p_tenant_id: string;
          p_parent: unknown;
          p_students: unknown;
          p_actor_profile_id: string;
          p_activation_code?: string | null;
        };
        Returns: unknown;
      };
      collect_payment: {
        Args: Record<string, unknown>;
        Returns: unknown;
      };
      refund_payment: {
        Args: { p_tenant_id: string; p_payment_id: string; p_actor_profile_id: string; p_reason: string };
        Returns: string;
      };
      /**
       * UNIFIED ARCHITECTURE: Atomic payment collection + waterfall allocation.
       *
       * Replaces the multi-step client-side flow (insert payment → insert
       * ledger entry → update installments) with a single RPC that wraps
       * everything in BEGIN ... COMMIT. If any step fails, the entire
       * transaction rolls back — no partial state is ever visible.
       *
       * Implementation: `supabase/migrations/0026_unified_financial.sql`.
       */
      collect_and_allocate_payment: {
        Args: {
          p_tenant_id: string;
          p_parent_id: string;
          p_student_id: string | null;
          p_amount: number;
          p_method: "cash" | "check" | "transfer";
          p_category: string;
          p_installment_id: string | null;
          p_proof_path: string | null;
          p_notes: string | null;
          p_actor_id: string;
          p_actor_name: string;
        };
        Returns: {
          payment_id: string;
          receipt_number: string;
          payment_status: string;
          total_allocated: number;
          unallocated_credit: number;
          allocations: unknown; // JSONB array of { installmentId, allocatedAmount, newAmountPaid, newStatus, fullySatisfied }
        };
      };
      /**
       * UNIFIED ARCHITECTURE: Atomic payment reversal + LIFO un-allocation.
       *
       * Replaces the multi-step client-side refund flow (mark refunded →
       * append reversal entry → revert installment amountPaid) with a
       * single RPC. Implements Invariant 5 (Reversal Balance).
       *
       * Implementation: `supabase/migrations/0026_unified_financial.sql`.
       */
      revert_payment_allocation: {
        Args: {
          p_tenant_id: string;
          p_payment_id: string;
          p_actor_id: string;
          p_actor_name: string;
          p_reason: string;
        };
        Returns: {
          payment_id: string;
          new_status: string;
          reversal_entry_id: string;
          reverts_count: number;
          total_reverted: number;
        };
      };
      run_overdue_scan: { Args: { p_tenant_id: string; p_as_of?: string }; Returns: unknown };
      expire_pending_approvals: { Args: Record<string, never>; Returns: number };
      refresh_all_materialized_views: { Args: Record<string, never>; Returns: void };
    };
  };
}
